import java.util.Scanner;

public class Main {
    static final int N = 250010;
    static long[] fac = new long[N];
    static long[] inv = new long[N];
    static long[][] dp = new long[30][N];
    static int[] bit = new int[N];

    static long com(int n, int m, long mod) {
        return fac[n] * inv[n - m] % mod * inv[m] % mod;
    }

    static void add(long[] x, int index, long y, long mod) {
        x[index] += y;
        if (x[index] >= mod) x[index] %= mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();
        long mod = sc.nextLong();

        inv[0] = fac[0] = 1;
        inv[1] = fac[1] = 1;

        for (int i = 2; i <= n; i++) {
            int r = (int) (mod / i);
            int x = (int) (mod - i * r);
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = mod - (long) r * inv[x] % mod;
        }
        for (int i = 2; i <= n; i++) {
            inv[i] = inv[i - 1] * inv[i] % mod;
        }

        long ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = ans * m % mod;
        }

        for (int i = 1; i <= n; i++) {
            bit[i] = bit[i >> 1] + (i & 1);
        }

        if ((n & 1) == 1) {
            System.out.println(ans);
            return;
        }

        dp[0][0] = 1;
        int minBitN = Math.min(0 + bit[(int) n], (int) m);
        for (int i = 0; i < minBitN; i++) {
            for (int j = 0; j < n; j++) {
                if (dp[i][j] == 0) continue;
                int x = (int) (n ^ j);
                for (int k = x, r; k > j; k = (k - 1) & x) {
                    r = k | j;
                    add(dp[i + 1], r, dp[i][j] * inv[k] % mod, mod);
                }
            }
        }

        for (int i = 1; i <= m; i++) {
            long temp = dp[i][(int) n] * fac[(int) m] % mod * inv[(int) (m - i)] % mod * fac[(int) n] % mod;
            ans -= temp;
        }
        ans = (mod + ans % mod) % mod;
        System.out.println(ans);
        sc.close();
    }
}

